def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    rows = [r for r in range(h) if 3 in grid[r]]
    top, bottom = min(rows), max(rows)
    cols = [c for r in range(h) for c in range(w) if grid[r][c] == 3]
    left, right = min(cols), max(cols)

    # Fill the frame interior and locate its internal green marker.
    markers = []
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            out[r][c] = 4
            if grid[r][c] == 3:
                markers.append((r, c))

    # Draw successively larger square outlines around the marker,
    # with radii 2, 4, 6, ... .
    if markers:
        mr, mc = markers[0]
        for r in range(top + 1, bottom):
            for c in range(left + 1, right):
                distance = max(abs(r - mr), abs(c - mc))
                if distance > 0 and distance % 2 == 0:
                    out[r][c] = 2
        out[mr][mc] = 3

    return out
